,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    id,',
'    app.idpoliza,',
'    app.CLV_DOCUMENTO_GRUPO,',
'    app.CLV_DOCUMENTO,',
'    p.fecinivig,',
'    p.fecfinvig,',
'    p.numpolunico,',
'    app.created  "Fecha Subida",',
'    app.created_by  "Subido por",',
unistr('    app.UPDATED "Ultima Actualizaci\00F3n",'),
'    app.UPDATED_BY "Actualizado por",',
'    app.archivo_blob,',
'    regexp_replace(app.nombre_archivo, ''\.[^.]+$'', '''') nombre_archivo,',
'    app.file_mime_type,',
'    app.file_charset,',
'    app.tamanio_bytes',
'FROM',
'         archivos_polizas app',
'    JOIN polizas p ON app.idpoliza = p.idpoliza',
'WHERE',
