,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'    IDARCHIVO_POLIZA,',
'    IDPOLIZA,',
'    CODEMPRESA,',
'    CODCIA,',
'    NOMBRE_ARCHIVO,',
'    VERSION,',
