,p_name=>'AccionesTopArchivos'
,p_data_source_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_sql         CLOB;',
'    l_col         VARCHAR2(30);',
'    l_fech        VARCHAR2(30);',
'    l_fecha_ini   DATE;',
'    l_fecha_fin   DATE;',
'BEGIN',
unistr('    -- Determinar columna y campo de fecha seg\00FAn acci\00F3n'),
'    CASE :P80_ACCIONARCHIVO',
'        WHEN ''CREATED_BY'' THEN ',
'            l_col := ''CREATED_BY'';',
'            l_fech := ''CREATED'';',
'        WHEN ''DELETED_BY'' THEN ',
'            l_col := ''DELETED_BY'';',
'            l_fech := ''DELETED'';',
'        WHEN ''UPDATED_BY'' THEN ',
'            l_col := ''UPDATED_BY'';',
'            l_fech := ''UPDATED'';',
'        ELSE ',
'            l_col := ''CREATED_BY'';',
'            l_fech := ''CREATED'';',
'    END CASE;',
'',
'    -- Convertir los valores texto a fecha',
'    l_fecha_ini := NVL(',
'        TO_DATE(:P80_FECHA_INICIO, ''YYYY-MM-DD''),',
'        ADD_MONTHS(TRUNC(SYSDATE), -1)',
'    );',
'',
'    l_fecha_fin := NVL(',
'        TO_DATE(:P80_FECHA_FIN, ''YYYY-MM-DD''),',
'        TRUNC(SYSDATE) - 1',
'    );',
'',
unistr('    -- Construir el SQL din\00E1mico'),
'    l_sql := ',
'        ''SELECT u.NOMUSUARIO AS usuario, COUNT(*) AS total '' ||',
'        ''FROM ARCHIVOS_POLIZAS a '' ||',
'        ''JOIN USUARIOS u ON a.'' || l_col || '' = u.CODUSUARIO '' ||',
'        ''WHERE a.'' || l_col || '' IS NOT NULL '' || ',
'        ''AND a.'' || l_fech || '' BETWEEN TO_DATE('''''' || TO_CHAR(l_fecha_ini, ''YYYY-MM-DD'') || '''''', ''''YYYY-MM-DD'''') '' ||',
'        ''AND TO_DATE('''''' || TO_CHAR(l_fecha_fin, ''YYYY-MM-DD'') || '''''', ''''YYYY-MM-DD'''') '' ||',
'        ''GROUP BY u.NOMUSUARIO '' ||',
'        ''ORDER BY total DESC'';',
'',
'    RETURN l_sql;',
'END;',
''))
,p_ajax_items_to_submit=>'P80_ACCIONARCHIVO,P80_FECHA_INICIO,P80_FECHA_FIN'
,p_items_value_column_name=>'TOTAL'
,p_items_label_column_name=>'USUARIO'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
);
