'SELECT',
'    (SELECT COUNT(*) FROM ARCHIVOS_POLIZAS WHERE ESTATUS_BORRADO = ''N'') AS TOTAL_ARCHIVOS,',
'    (SELECT COUNT(*) FROM POLIZAS) AS TOTAL_POLIZAS,',
'    (SELECT COUNT(DISTINCT IDPOLIZA) FROM ARCHIVOS_POLIZAS WHERE ESTATUS_BORRADO = ''N'') AS POLIZAS_CON_ARCHIVOS,',
'    TO_CHAR(ROUND(',
'        (SELECT COUNT(DISTINCT IDPOLIZA) FROM ARCHIVOS_POLIZAS WHERE ESTATUS_BORRADO = ''N'') * 100 /',
