'        2',
'    )) || ''%'' AS "PORCENTAJE DE POLIZAS CON ARCHIVOS",',
'    ROUND(',
'        (SELECT AVG(CNT) FROM (',
'            SELECT COUNT(*) AS CNT',
'            FROM ARCHIVOS_POLIZAS',
'            WHERE ESTATUS_BORRADO = ''N''',
'            GROUP BY IDPOLIZA',
'        )),',
'        2',
'    ) AS "PROMEDIO DE ARCHIVOS POR POLIZA"',
'FROM DUAL;',
